641:   @Test
642:   public void test() {
643:     // when we trigger the scenario and initiate command distribution
644:     final var event = scenario.commandSender.sendCommand();
645:     final var distributionCommand =
646:         RecordingExporter.commandDistributionRecords(CommandDistributionIntent.STARTED)
647:             .withSourceRecordPosition(event.getSourceRecordPosition())
648:             .filter(a -> scenario.matches(a.getValue()))
649:             .getFirst();
