808:   private static class AcknowledgementInterceptor {
809:     private final CompletableFuture<Record<CommandDistributionRecordValue>> signal =
810:         new CompletableFuture();
811:     private final AtomicInteger acknowledgeCount = new AtomicInteger(0);
812: 
813:     private final Scenario scenario;
814: 
815:     public AcknowledgementInterceptor(final Scenario scenario) {
816:       this.scenario = scenario;
817:     }
818: 
819:     /**
820:      * Creates an interceptor for the given scenario and registers it with the engine
821:      *
822:      * @param scenario to match with the intercepted commands
823:      * @return interceptor instance create
824:      */
825:     public static AcknowledgementInterceptor create(final Scenario scenario) {
826:       final var interceptor = new AcknowledgementInterceptor(scenario);
827:       ENGINE.interceptInterPartitionCommands(interceptor::shouldPassCommand);
828:       return interceptor;
829:     }
830: 
831:     /**
832:      * Closes the interceptor
833:      *
834:      * <p>It cancels the future it might wait for to unblock the thread and unregisters it from the
835:      * engine
836:      */
837:     public void close() {
838:       ENGINE.interceptInterPartitionCommands(CommandInterceptor.SEND_ALL);
839: 
840:       if (signal.isCompletedExceptionally()) {
841:         fail(
842:             "Interceptor hasn't received a signal in time, and thus couldn't do any interceptions");
843:       } else {
844:         signal.cancel(true);
845:       }
846:     }
847: 
848:     /**
849:      * Signals that the initial command distribution started and allows to identify the
850:      * acknowledgements we want to intercept
851:      *
852:      * @param distributionCommand
853:      */
854:     public void enable(final Record<CommandDistributionRecordValue> distributionCommand) {
855:       signal.complete(distributionCommand);
856:     }
857: 
858:     /**
859:      * This method will be called for all inter-partition commands
860:      *
861:      * <p>Attention: this also means for commands that are not related to the scenario, or we don't
862:      * want to swallow
863:      */
864:     private boolean shouldPassCommand(
865:         final int targetPartitionId,
866:         final ValueType valueType,
867:         final Intent intent,
868:         final Long recordKey,
869:         final UnifiedRecordValue commandValue) {
870: 
871:       if (matchesScenario(intent, recordKey, commandValue)) {
872:         // intercept the first acknowledgement, pass on the rest
873:         return acknowledgeCount.incrementAndGet() > 1;
874:       }
875: 
876:       return true;
877:     }
878: 
879:     private boolean matchesScenario(
880:         final Intent intent, final Long recordKey, final UnifiedRecordValue commandValue) {
881:       // allow other inter-partition commands to continue without waiting for the signal
882:       if (intent != CommandDistributionIntent.ACKNOWLEDGE) {
883:         return false;
884:       }
885: 
886:       // allow other distribution commands to continue early and not wait for the signal
887:       if (!scenario.matches((CommandDistributionRecordValue) commandValue)) {
888:         return false;
889:       }
890: 
891:       return getScenarioKey().map(recordKey::equals).orElse(false);
892:     }
893: 
894:     private Optional<Long> getScenarioKey() {
895:       try {
896:         return Optional.of(signal.get(5000, TimeUnit.MILLISECONDS).getKey());
897:       } catch (final InterruptedException
898:           | ExecutionException
899:           | TimeoutException
900:           | CancellationException e) {
901:         // complete the future, let the commands pass, but make sure to fail the test
902:         if (!signal.isDone()) {
903:           signal.completeExceptionally(e);
904:         }
905:         return Optional.empty();
906:       }
907:     }
908:   }
