641:   @Test
642:   public void test() {
643:     // when we trigger the scenario and initiate command distribution
644:     final var event = scenario.commandSender.sendCommand();
645:     final var distributionCommand =
646:         RecordingExporter.commandDistributionRecords(CommandDistributionIntent.STARTED)
647:             .withSourceRecordPosition(event.getSourceRecordPosition())
648:             .filter(a -> scenario.matches(a.getValue()))
649:             .getFirst();
650: 
651:     // given we intercept the first acknowledgement of the command distribution
652:     interceptor.enable(distributionCommand);
653: 
654:     // then we expect the command will written to the target partition twice (retry)
655:     RecordingExporter.setMaximumWaitTime(100);
656:     Awaitility.await()
657:         .untilAsserted(
658:             () -> {
659:               // wait for retry mechanism to trigger second distribution
660:               // (while we intercepted the first acknowledgement)
661:               ENGINE.getClock().addTime(CommandRedistributor.COMMAND_REDISTRIBUTION_INTERVAL);
662: 
663:               // Make sure we have two records on the target partition
664:               assertThat(
665:                       RecordingExporter.records()
666:                           .withPartitionId(2)
667:                           .withValueType(distributionCommand.getValue().getValueType())
668:                           .withIntent(distributionCommand.getValue().getIntent())
669:                           .withRecordKey(distributionCommand.getKey())
670:                           .limit(2))
671:                   .hasSize(2);
672:             });
673:     RecordingExporter.setMaximumWaitTime(5000);
674: 
675:     // then we expect the distribution still finishes based on the second (retried) acknowledgement
676:     assertThat(
677:             RecordingExporter.commandDistributionRecords(CommandDistributionIntent.FINISHED)
678:                 .withPartitionId(1)
679:                 .withRecordKey(distributionCommand.getKey())
680:                 .exists())
681:         .isTrue();
682:   }
