745:   private static Record<ProcessInstanceMigrationRecordValue> migrateMessageSubscription() {
746:     // given
747:     final String processId = "process1";
748:     final String targetProcessId = "process2";
749:     // the process instance on partition 1 will wait for a message published on 2
750:     final var correlationKey = "correlationKey";
751: 
752:     final var deployment =
753:         ENGINE
754:             .deployment()
755:             .withXmlResource(
756:                 Bpmn.createExecutableProcess(processId)
757:                     .startEvent()
758:                     .userTask("A")
759:                     .boundaryEvent("boundary1")
760:                     .message(m -> m.name("message").zeebeCorrelationKeyExpression("key1"))
761:                     .endEvent()
762:                     .moveToActivity("A")
763:                     .endEvent()
764:                     .done())
765:             .withXmlResource(
766:                 Bpmn.createExecutableProcess(targetProcessId)
767:                     .startEvent()
768:                     .userTask("B")
769:                     .boundaryEvent("boundary2")
770:                     .message(m -> m.name("message").zeebeCorrelationKeyExpression("key2"))
771:                     .endEvent()
772:                     .moveToActivity("B")
773:                     .endEvent()
774:                     .done())
775:             .deploy();
776:     final long targetProcessDefinitionKey =
777:         extractProcessDefinitionKeyByProcessId(deployment, targetProcessId);
778: 
779:     final var processInstanceKey =
780:         ENGINE
781:             .processInstance()
782:             .ofBpmnProcessId(processId)
783:             .withVariables(Map.of("key1", correlationKey))
784:             .create();
785: 
786:     RecordingExporter.messageSubscriptionRecords(MessageSubscriptionIntent.CREATED)
787:         .withProcessInstanceKey(processInstanceKey)
788:         .await();
789: 
790:     // when
791:     return ENGINE
792:         .processInstance()
793:         .withInstanceKey(processInstanceKey)
794:         .migration()
795:         .withTargetProcessDefinitionKey(targetProcessDefinitionKey)
796:         .addMappingInstruction("A", "B")
797:         .addMappingInstruction("boundary1", "boundary2")
798:         .migrate();
799:   }
