200:             tuple(commandIntent, RecordType.COMMAND, 1),
201:             tuple(eventIntent, RecordType.EVENT, 1),
202:             tuple(CommandDistributionIntent.STARTED, RecordType.EVENT, 1))
203:         .containsSubsequence(
204:             tuple(CommandDistributionIntent.DISTRIBUTING, RecordType.EVENT, 2),
205:             tuple(CommandDistributionIntent.ACKNOWLEDGE, RecordType.COMMAND, 2),
206:             tuple(CommandDistributionIntent.ACKNOWLEDGED, RecordType.EVENT, 2))
207:         .containsSubsequence(
208:             tuple(CommandDistributionIntent.DISTRIBUTING, RecordType.EVENT, 3),
209:             tuple(CommandDistributionIntent.ACKNOWLEDGE, RecordType.COMMAND, 3),
210:             tuple(CommandDistributionIntent.ACKNOWLEDGED, RecordType.EVENT, 3))
211:         .endsWith(tuple(CommandDistributionIntent.FINISHED, RecordType.EVENT, 1));
