443:   private static ExecutorResource buildExecutorService(
444:       final CamundaClientConfiguration configuration) {
445:     if (configuration.jobWorkerExecutor() != null) {
446:       return new ExecutorResource(
447:           configuration.jobWorkerExecutor(), configuration.ownsJobWorkerExecutor());
448:     }
449: 
450:     final int threadCount = configuration.getNumJobWorkerExecutionThreads();
451:     final ScheduledExecutorService executor = Executors.newScheduledThreadPool(threadCount);
452:     return new ExecutorResource(executor, true);
453:   }
