411:   public static GatewayStub buildGatewayStub(
412:       final ManagedChannel channel, final CamundaClientConfiguration config) {
413:     final CallCredentials credentials = buildCallCredentials(config);
414:     final GatewayStub gatewayStub = GatewayGrpc.newStub(channel).withCallCredentials(credentials);
415:     if (!config.getInterceptors().isEmpty()) {
416:       return gatewayStub.withInterceptors(
417:           config.getInterceptors().toArray(new ClientInterceptor[] {}));
418:     }
419:     return gatewayStub;
420:   }
