422:   private static Map<String, Object> defaultServiceConfig() {
423:     final ObjectMapper objectMapper = new ObjectMapper();
424:     final URL defaultServiceConfig =
425:         ClassLoader.getSystemClassLoader().getResource("gateway-service-config.json");
426:     if (defaultServiceConfig == null) {
427:       Loggers.LOGGER.info(
428:           "No default service config found on classpath; will not configure a default retry policy");
429:       return new HashMap<>();
430:     }
431: 
432:     try {
433:       return objectMapper.readValue(
434:           defaultServiceConfig, new TypeReference<Map<String, Object>>() {});
435:     } catch (final IOException e) {
436:       Loggers.LOGGER.warn(
437:           "Failed to read default service config from classpath; will not configure a default retry policy",
438:           e);
439:       return new HashMap<>();
440:     }
441:   }
