349:   public static ManagedChannel buildChannel(final CamundaClientConfiguration config) {
350:     final URI address;
351:     address = config.getGrpcAddress();
352: 
353:     final NettyChannelBuilder channelBuilder =
354:         NettyChannelBuilder.forAddress(address.getHost(), address.getPort());
355: 
356:     configureConnectionSecurity(config, channelBuilder);
357:     channelBuilder.keepAliveTime(config.getKeepAlive().toMillis(), TimeUnit.MILLISECONDS);
358:     channelBuilder.userAgent("camunda-client-java/" + VersionUtil.getVersion());
359:     channelBuilder.maxInboundMessageSize(config.getMaxMessageSize());
360:     channelBuilder.maxInboundMetadataSize(config.getMaxMetadataSize());
361: 
362:     if (config.useDefaultRetryPolicy()) {
363:       final Map<String, Object> serviceConfig = defaultServiceConfig();
364:       if (!serviceConfig.isEmpty()) {
365:         channelBuilder.defaultServiceConfig(serviceConfig);
366:         channelBuilder.enableRetry();
367:       }
368:     }
369: 
370:     return channelBuilder.build();
371:   }
372: 
373:   private static CallCredentials buildCallCredentials(final CamundaClientConfiguration config) {
374:     final CredentialsProvider customCredentialsProvider = config.getCredentialsProvider();
375: 
376:     if (customCredentialsProvider == null) {
377:       return null;
378:     }
379: 
380:     return new CamundaCallCredentials(customCredentialsProvider);
381:   }
382: 
383:   private static void configureConnectionSecurity(
384:       final CamundaClientConfiguration config, final NettyChannelBuilder channelBuilder) {
385:     if (!config.isPlaintextConnectionEnabled()) {
386:       final String certificatePath = config.getCaCertificatePath();
387:       SslContext sslContext = null;
388: 
389:       if (certificatePath != null) {
390:         if (certificatePath.isEmpty()) {
391:           throw new IllegalArgumentException(
392:               "Expected valid certificate path but found empty path instead.");
393:         }
394: 
395:         try (final FileInputStream certInputStream = new FileInputStream(certificatePath)) {
396:           sslContext = GrpcSslContexts.forClient().trustManager(certInputStream).build();
397:         } catch (final IOException e) {
398:           throw new RuntimeException(e);
399:         }
400:       }
401: 
402:       channelBuilder.useTransportSecurity().sslContext(sslContext);
403:       if (config.getOverrideAuthority() != null) {
404:         channelBuilder.overrideAuthority(config.getOverrideAuthority());
405:       }
406:     } else {
407:       channelBuilder.usePlaintext();
408:     }
409:   }
410: 
411:   public static GatewayStub buildGatewayStub(
412:       final ManagedChannel channel, final CamundaClientConfiguration config) {
413:     final CallCredentials credentials = buildCallCredentials(config);
414:     final GatewayStub gatewayStub = GatewayGrpc.newStub(channel).withCallCredentials(credentials);
415:     if (!config.getInterceptors().isEmpty()) {
416:       return gatewayStub.withInterceptors(
417:           config.getInterceptors().toArray(new ClientInterceptor[] {}));
418:     }
419:     return gatewayStub;
420:   }
