470:   @Override
471:   public void close() {
472:     closeables.forEach(
473:         c -> {
474:           try {
475:             c.close();
476:           } catch (final IOException e) {
477:             // ignore
478:           }
479:         });
480: 
481:     executorResource.close();
482:     channel.shutdownNow();
483: 
484:     try {
485:       if (!channel.awaitTermination(15, TimeUnit.SECONDS)) {
486:         throw new ClientException(
487:             "Timed out awaiting termination of in-flight request channel after 15 seconds");
488:       }
489:     } catch (final InterruptedException e) {
490:       throw new ClientException(
491:           "Unexpectedly interrupted awaiting termination of in-flight request channel", e);
492:     }
493: 
494:     try {
495:       httpClient.close();
496:     } catch (final Exception e) {
497:       throw new ClientException("Failed closing http client.", e);
498:     }
499:   }
