349:   public static ManagedChannel buildChannel(final CamundaClientConfiguration config) {
350:     final URI address;
351:     address = config.getGrpcAddress();
352: 
353:     final NettyChannelBuilder channelBuilder =
354:         NettyChannelBuilder.forAddress(address.getHost(), address.getPort());
355: 
356:     configureConnectionSecurity(config, channelBuilder);
357:     channelBuilder.keepAliveTime(config.getKeepAlive().toMillis(), TimeUnit.MILLISECONDS);
358:     channelBuilder.userAgent("camunda-client-java/" + VersionUtil.getVersion());
359:     channelBuilder.maxInboundMessageSize(config.getMaxMessageSize());
360:     channelBuilder.maxInboundMetadataSize(config.getMaxMetadataSize());
361: 
362:     if (config.useDefaultRetryPolicy()) {
363:       final Map<String, Object> serviceConfig = defaultServiceConfig();
364:       if (!serviceConfig.isEmpty()) {
365:         channelBuilder.defaultServiceConfig(serviceConfig);
366:         channelBuilder.enableRetry();
367:       }
368:     }
369: 
370:     return channelBuilder.build();
371:   }
