383:   private static void configureConnectionSecurity(
384:       final CamundaClientConfiguration config, final NettyChannelBuilder channelBuilder) {
385:     if (!config.isPlaintextConnectionEnabled()) {
386:       final String certificatePath = config.getCaCertificatePath();
387:       SslContext sslContext = null;
388: 
389:       if (certificatePath != null) {
390:         if (certificatePath.isEmpty()) {
391:           throw new IllegalArgumentException(
392:               "Expected valid certificate path but found empty path instead.");
393:         }
394: 
395:         try (final FileInputStream certInputStream = new FileInputStream(certificatePath)) {
396:           sslContext = GrpcSslContexts.forClient().trustManager(certInputStream).build();
397:         } catch (final IOException e) {
398:           throw new RuntimeException(e);
399:         }
400:       }
401: 
402:       channelBuilder.useTransportSecurity().sslContext(sslContext);
403:       if (config.getOverrideAuthority() != null) {
404:         channelBuilder.overrideAuthority(config.getOverrideAuthority());
405:       }
406:     } else {
407:       channelBuilder.usePlaintext();
408:     }
409:   }
