533:    *
534:    * <pre>
535:    * public final class PaymentHandler implements JobHandler
536:    * {
537:    *   &#64;Override
538:    *   public void handle(JobClient client, JobEvent jobEvent)
539:    *   {
540:    *     String json = jobEvent.getVariables();
541:    *     // modify variables
542:    *
543:    *     client
544:    *      .newCompleteCommand()
545:    *      .event(jobEvent)
546:    *      .variables(json)
547:    *      .send();
548:    *   }
549:    * };
550:    * </pre>
