266:   /**
267:    * Command to migrate a process instance to a different process definition.
268:    *
269:    * <p>The migration command contains a migration plan. Migration plan contains
270:    * targetProcessDefinitionKey to indicate which process definition to use for the migration.
271:    * Mapping instructions for the migration describe how to map elements from the source process
272:    * definition to the target process definition.
273:    *
274:    * <p>For example, let's consider we want to migrate process instance with key {@code 1}, target
275:    * process definition key {@code 2}, a source process definition with a service task with id
276:    * {@code "task1"} and the target process definition with a service task with id {@code "task2"}.
277:    * The migration command could be:
278:    *
279:    * <pre>{@code
280:    * {
281:    *  "processInstanceKey": 1,
282:    *  "migrationPlan": {
283:    *   "targetProcessDefinitionKey": 2,
284:    *   "mappingInstructions": [
285:    *    {
286:    *     "sourceElementId": "task1",
287:    *     "targetElementId": "task2"
288:    *    }
289:    *   ]
290:    *  }
291:    * }
292:    * }</pre>
293:    *
294:    * <pre>
295:    *
296:    * camundaClient
297:    *  .newMigrateProcessInstanceCommand(1L)
298:    *  .migrationPlan(2L)
299:    *  .addMappingInstruction("element1", "element2")
300:    *  .addMappingInstruction("element3", "element4")
301:    *  .send();
302:    * </pre>
303:    *
304:    * <pre>
305:    * final MigrationPlan migrationPlan =
306:    *         MigrationPlan.newBuilder()
307:    *             .withTargetProcessDefinitionKey(2L)
308:    *             .addMappingInstruction("element1", "element2")
309:    *             .addMappingInstruction("element3", "element4")
310:    *             .build();
311:    * camundaClient
312:    *  .newMigrateProcessInstanceCommand(1L)
313:    *  .migrationPlan(migrationPlan)
314:    *  .send();
315:    * </pre>
316:    *
317:    * @param processInstanceKey the key which refers to the process instance to migrate
318:    * @return a builder for the command
319:    */
320:   @ExperimentalApi("https://github.com/camunda/camunda/issues/14907")
321:   MigrateProcessInstanceCommandStep1 newMigrateProcessInstanceCommand(long processInstanceKey);
