74:   @Override
75:   public void processNewCommand(final TypedRecord<TenantRecord> command) {
76:     final var record = command.getValue();
77:     final var tenantId = record.getTenantId();
78:     final var authorizationRequest =
79:         new AuthorizationRequest(command, AuthorizationResourceType.TENANT, PermissionType.UPDATE)
80:             .addResourceId(tenantId);
81:     final var isAuthorized = authCheckBehavior.isAuthorized(authorizationRequest);
82:     if (isAuthorized.isLeft()) {
83:       rejectCommandWithUnauthorizedError(command, isAuthorized.getLeft());
84:       return;
85:     }
86: 
87:     final var tenantLookup = getPersistedTenant(record);
88:     if (tenantLookup.isLeft()) {
89:       rejectCommand(command, RejectionType.NOT_FOUND, tenantLookup.getLeft());
90:       return;
