115:   @Override
116:   public void processDistributedCommand(final TypedRecord<TenantRecord> command) {
117:     final var record = command.getValue();
118:     if (isEntityAssigned(record)) {
119:       createAlreadyAssignedRejectCommand(
120:           command, record.getEntityId(), record.getEntityType(), record.getTenantId());
121:     } else {
122:       stateWriter.appendFollowUpEvent(command.getKey(), TenantIntent.ENTITY_ADDED, record);
123:     }
124: 
125:     commandDistributionBehavior.acknowledgeCommand(command);
126:   }
127: 
128:   /** Loads the persisted tenant by the tenant id. */
129:   private Either<String, PersistedTenant> getPersistedTenant(final TenantRecord record) {
130:     final var tenantId = record.getTenantId();
131:     return tenantState
132:         .getTenantById(tenantId)
133:         .<Either<String, PersistedTenant>>map(Either::right)
134:         .orElseGet(() -> Either.left(TENANT_NOT_FOUND_ERROR_MESSAGE.formatted(tenantId)));
135:   }
136: 
137:   private boolean isEntityPresent(
138:       final String entityId, final EntityType entityType, final boolean internalGroupsEnabled) {
139:     return switch (entityType) {
140:       case USER -> true; // With simple mappings, any username can be assigned
141:       case CLIENT -> true; // With simple mappings, any client id can be assigned
142:       case MAPPING -> mappingState.get(entityId).isPresent();
143:       case GROUP -> !internalGroupsEnabled || groupState.get(entityId).isPresent();
144:       case ROLE -> roleState.getRole(entityId).isPresent();
145:       default -> false;
146:     };
147:   }
